"""Collect the licence texts of every third-party Rust crate linked into the shipped binaries.

The wheel (`queuetruth._core`, crate `queuetruth-py`) and the standalone binary (`queuetruth-core`, crate
`queuetruth-cli`) statically link their Rust dependencies, so their licence notices ship with them. This script
lists the normal (non-dev, non-build) dependency tree of both packages with `cargo tree --locked --offline`, reads
each crate's licence files from the local cargo registry sources, and writes
`third_party/licenses/rust-crates.txt`: a table of crate, version and SPDX expression, then every distinct licence
text once, with the crates it belongs to. The file sits in `third_party/licenses/`, which `pyproject.toml` includes
in the wheel's licence files.

Usage (from the repository root):
    uv run --frozen --no-sync python third_party/gen_rust_licenses.py           # write the file
    uv run --frozen --no-sync python third_party/gen_rust_licenses.py --check   # exit 1 if it would change

Crates without a licence file in their source get a note naming their SPDX expression; the standard text for that
licence then applies (Apache-2.0 is in the repository's LICENSE).
"""

from __future__ import annotations

import argparse
import hashlib
import os
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "third_party" / "licenses" / "rust-crates.txt"
PACKAGES = ["queuetruth-py", "queuetruth-cli"]
LICENSE_FILE = re.compile(r"^(LICEN[CS]E|COPYING|COPYRIGHT|NOTICE|UNLICENSE)([-_.].*)?$", re.I)


def registry_dirs() -> list[Path]:
    home = Path(os.environ.get("CARGO_HOME", Path.home() / ".cargo"))
    return sorted((home / "registry" / "src").glob("*"))


def crates() -> dict[tuple[str, str], str]:
    """(name, version) -> SPDX licence, for every non-workspace crate in the normal tree of PACKAGES."""
    out: dict[tuple[str, str], str] = {}
    for pkg in PACKAGES:
        p = subprocess.run(
            [
                "cargo",
                "tree",
                "--locked",
                "--offline",
                "-p",
                pkg,
                "-e",
                "normal",
                "--prefix",
                "none",
                "--format",
                "{p}|{l}",
            ],
            cwd=ROOT,
            text=True,
            capture_output=True,
            check=True,
        )
        for line in p.stdout.splitlines():
            line = line.replace(" (*)", "").strip()
            if not line or "|" not in line:
                continue
            spec, lic = line.split("|", 1)
            parts = spec.split()
            if len(parts) < 2 or len(parts) > 2:  # path dependencies print "(path)" as a third part
                continue
            name, ver = parts[0], parts[1].lstrip("v")
            out[(name, ver)] = lic.strip() or "(none declared)"
    return dict(sorted(out.items()))


def licence_files(name: str, ver: str) -> list[Path]:
    for reg in registry_dirs():
        d = reg / f"{name}-{ver}"
        if d.is_dir():
            return sorted(f for f in d.iterdir() if f.is_file() and LICENSE_FILE.match(f.name))
    return []


def render() -> str:
    table = crates()
    texts: dict[str, tuple[str, list[str]]] = {}
    missing: list[str] = []
    for (name, ver), _lic in table.items():
        files = licence_files(name, ver)
        if not files:
            missing.append(f"{name} {ver}")
        for f in files:
            body = f.read_text(encoding="utf-8", errors="replace").replace("\r\n", "\n").strip() + "\n"
            h = hashlib.sha256(body.encode()).hexdigest()
            texts.setdefault(h, (body, []))[1].append(f"{name} {ver} ({f.name})")
    lines = [
        "Third-party Rust crates linked into queuetruth._core and queuetruth-core",
        "",
        "Generated by third_party/gen_rust_licenses.py from Cargo.lock (normal dependencies of queuetruth-py and",
        "queuetruth-cli). Each distinct licence text is reproduced once below, followed by the crates it covers.",
        "",
        f"{'crate':40s} {'version':24s} licence",
        "-" * 100,
    ]
    lines += [f"{n:40s} {v:24s} {lic}" for (n, v), lic in table.items()]
    if missing:
        lines += ["", "Crates whose source has no licence file (the standard text of their declared licence applies):"]
        lines += [f"  {m}: {table[tuple(m.split(' ', 1))]}" for m in missing]
    for _h, (body, owners) in sorted(texts.items(), key=lambda kv: kv[1][1][0]):
        lines += ["", "=" * 100, "Applies to: " + ", ".join(owners), "=" * 100, "", body.rstrip()]
    text = "\n".join(lines) + "\n"
    return text.replace(chr(0x2014), "-").replace(chr(0x2013), "-")


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="collect Rust crate licence texts")
    ap.add_argument("--check", action="store_true", help="exit 1 if the committed file is out of date")
    a = ap.parse_args(argv)
    text = render()
    if a.check:
        if not OUT.exists() or OUT.read_text(encoding="utf-8") != text:
            print(f"{OUT.relative_to(ROOT)} is out of date; rerun third_party/gen_rust_licenses.py")
            return 1
        return 0
    OUT.write_text(text, encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)} ({len(text.splitlines())} lines)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
